_base_tables=_tables
def _tables():
    rows,corners,scalar,pos,edge,tern,mirror=_base_tables()
    residual=np.frombuffer(zlib.decompress(base64.b85decode(_RICH_MODEL)),dtype='<f4').reshape(7,32805)
    empty=np.arange(61);lo=np.clip((empty-4)//8,0,5)
    a=np.clip((empty-(4+lo*8))/8,0,1).astype(np.float32)
    w=100*((1-a[:,None])*residual[lo]+a[:,None]*residual[lo+1])
    digits=(np.arange(6561)[:,None]//(3**np.arange(8)))%3
    reverse=digits[:,::-1]@(3**np.arange(8))
    def rounded(x):
        y=(np.sign(x)*np.floor(abs(x)+.5))
        if np.any(y < -32768) or np.any(y > 32767):raise ValueError('learned table overflow')
        return y.astype(np.int16)
    for group in range(4):
        offset=group*6561
        rows[:,group]=rounded(rows[:,group].astype(np.float32)+w[:,offset+np.arange(6561)]+w[:,offset+reverse])
    corners=rounded(corners[:,np.arange(6561)%729].astype(np.float32)+w[:,4*6561:])
    mirror=np.zeros(256,dtype=np.int32)
    for j,source in enumerate((2,1,0,5,4,3,7,6)):
        mirror+=((np.arange(256)>>source)&1)*3**j
    return rows,corners,scalar,pos,edge,tern,mirror

@njit
def _corner_sum(p,o,table,tern,mirror):
    p0=int((p&np.uint64(7))|((p>>np.uint64(5))&np.uint64(56))|((p>>np.uint64(10))&np.uint64(192)))
    o0=int((o&np.uint64(7))|((o>>np.uint64(5))&np.uint64(56))|((o>>np.uint64(10))&np.uint64(192)))
    p1=int(((p>>np.uint64(5))&np.uint64(7))|((p>>np.uint64(10))&np.uint64(56))|((p>>np.uint64(16))&np.uint64(192)))
    o1=int(((o>>np.uint64(5))&np.uint64(7))|((o>>np.uint64(10))&np.uint64(56))|((o>>np.uint64(16))&np.uint64(192)))
    p2=int(((p>>np.uint64(56))&np.uint64(7))|((p>>np.uint64(45))&np.uint64(56))|((p>>np.uint64(34))&np.uint64(192)))
    o2=int(((o>>np.uint64(56))&np.uint64(7))|((o>>np.uint64(45))&np.uint64(56))|((o>>np.uint64(34))&np.uint64(192)))
    p3=int(((p>>np.uint64(61))&np.uint64(7))|((p>>np.uint64(50))&np.uint64(56))|((p>>np.uint64(40))&np.uint64(192)))
    o3=int(((o>>np.uint64(61))&np.uint64(7))|((o>>np.uint64(50))&np.uint64(56))|((o>>np.uint64(40))&np.uint64(192)))
    return table[tern[p0]+2*tern[o0]]+table[mirror[p1]+2*mirror[o1]]+table[tern[p2]+2*tern[o2]]+table[mirror[p3]+2*mirror[o3]]

